package com.aliothmoon.maafw.once;
import org.junit.*;import org.junit.rules.TemporaryFolder;import java.nio.file.*;import java.nio.file.attribute.FileTime;import java.util.concurrent.atomic.AtomicLong;import static org.junit.Assert.*;
public class OwnStateReadOnlyFilesTest {
 @Rule public TemporaryFolder temp=new TemporaryFolder();
 private Path root(){return temp.getRoot().toPath().toAbsolutePath();}
 // Windows lacks native fileKey; only synthetic tests supply deterministic identity. Production never falls back.
 private final OwnStateReadOnlyFiles.Attributes attributes=path->{var a=Files.readAttributes(path,java.nio.file.attribute.BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS);return new java.nio.file.attribute.BasicFileAttributes(){public FileTime lastModifiedTime(){return a.lastModifiedTime();}public FileTime lastAccessTime(){return a.lastAccessTime();}public FileTime creationTime(){return a.creationTime();}public boolean isRegularFile(){return a.isRegularFile();}public boolean isDirectory(){return a.isDirectory();}public boolean isSymbolicLink(){return a.isSymbolicLink();}public boolean isOther(){return a.isOther();}public long size(){return a.size();}public Object fileKey(){return path.toString()+a.creationTime();}};};
 private OwnStateReadOnlyFiles.Result read(String name){return OwnStateReadOnlyFiles.readForTest(root(),name,1000,()->1,()->{},attributes);}
 @Test public void absentRootAndFileNeverCreated(){Path absent=root().resolve("missing");assertEquals(OwnStateReadOnlyFiles.Status.ABSENT_LOCAL,OwnStateReadOnlyFiles.readForTest(absent,"x",1000,()->1,()->{},attributes).status());assertFalse(Files.exists(absent));assertEquals(OwnStateReadOnlyFiles.Status.ABSENT_LOCAL,read("missing/x").status());assertFalse(Files.exists(root().resolve("missing")));}
 @Test public void regularAndEmptyBytesAreInternalAndReadOnly()throws Exception{Path f=root().resolve("state");Files.write(f,new byte[]{1,2,3});var before=Files.readAttributes(f,java.nio.file.attribute.BasicFileAttributes.class);var r=read("state");assertEquals(OwnStateReadOnlyFiles.Status.REGULAR_BYTES,r.status());assertArrayEquals(new byte[]{1,2,3},r.bytes());byte[] copy=r.bytes();copy[0]=9;assertEquals(1,r.bytes()[0]);assertArrayEquals(new byte[]{1,2,3},Files.readAllBytes(f));assertEquals(before.lastModifiedTime(),Files.getLastModifiedTime(f));assertFalse(r.summary().contains(root().toString()));r.clear();assertArrayEquals(new byte[3],r.bytes());Files.write(root().resolve("empty"),new byte[0]);assertEquals(0,read("empty").bytes().length);}
 @Test public void capAndDirectoryRejected()throws Exception{Files.write(root().resolve("big"),new byte[65537]);assertEquals(OwnStateReadOnlyFiles.Status.OVERSIZE,read("big").status());Files.write(root().resolve("max"),new byte[65536]);assertEquals(65536,read("max").bytes().length);Files.createDirectory(root().resolve("dir"));assertEquals(OwnStateReadOnlyFiles.Status.UNSAFE_PATH,read("dir").status());}
 @Test public void traversalAndAbsoluteRejected(){for(String s:new String[]{"../outside","a/../outside","./state",root().resolve("state").toString(),""})assertEquals(s,OwnStateReadOnlyFiles.Status.UNSAFE_PATH,read(s).status());}
 @Test public void mutationAfterReadFailsClosed()throws Exception{Path f=root().resolve("state");Files.write(f,new byte[]{1});var r=OwnStateReadOnlyFiles.readForTest(root(),"state",1000,()->1,()->{try{Files.write(f,new byte[]{2,3});}catch(Exception e){throw new RuntimeException(e);}},attributes);assertEquals(OwnStateReadOnlyFiles.Status.CHANGED,r.status());assertNull(r.bytes());}
 @Test public void sameSizeMtimeChangeFailsClosed()throws Exception{Path f=root().resolve("state");Files.write(f,new byte[]{1});var r=OwnStateReadOnlyFiles.readForTest(root(),"state",1000,()->1,()->{try{Files.setLastModifiedTime(f,FileTime.fromMillis(1234));}catch(Exception e){throw new RuntimeException(e);}},attributes);assertEquals(OwnStateReadOnlyFiles.Status.CHANGED,r.status());}
 @Test public void deadlineBeforeAndAfterReadRejects()throws Exception{Files.write(root().resolve("state"),new byte[]{1});assertEquals(OwnStateReadOnlyFiles.Status.EXPIRED,OwnStateReadOnlyFiles.read(root(),"state",1,()->1).status());AtomicLong now=new AtomicLong(1);assertEquals(OwnStateReadOnlyFiles.Status.EXPIRED,OwnStateReadOnlyFiles.readForTest(root(),"state",1000,now::get,()->now.set(1000),attributes).status());}
 @Test public void symlinkRootIntermediateAndFinalRejectedWhenSupported()throws Exception{Path actual=Files.createDirectory(root().resolve("actual"));Files.write(actual.resolve("state"),new byte[]{1});Path link=root().resolve("link");try{Files.createSymbolicLink(link,actual);}catch(java.io.IOException|UnsupportedOperationException|SecurityException unavailable){Assume.assumeNoException(unavailable);return;}assertEquals(OwnStateReadOnlyFiles.Status.UNSAFE_PATH,read("link/state").status());assertEquals(OwnStateReadOnlyFiles.Status.UNSAFE_PATH,OwnStateReadOnlyFiles.readForTest(link,"state",1000,()->1,()->{},attributes).status());Files.createSymbolicLink(root().resolve("filelink"),actual.resolve("state"));assertEquals(OwnStateReadOnlyFiles.Status.UNSAFE_PATH,read("filelink").status());}
 @Test public void nativeNullIdentityCannotBecomeReadable()throws Exception{Path f=root().resolve("native");Files.write(f,new byte[]{1});if(Files.readAttributes(f,java.nio.file.attribute.BasicFileAttributes.class).fileKey()==null){assertEquals(OwnStateReadOnlyFiles.Status.UNSAFE_PATH,OwnStateReadOnlyFiles.read(root(),"native",1000,()->1).status());assertEquals(OwnStateReadOnlyFiles.Status.UNSAFE_PATH,OwnStateReadOnlyFiles.inspect(root(),"native",1000,()->1).status());}}
 @Test public void metadataAbsentDoesNotCreateAnything(){Path absent=root().resolve("absent");assertEquals(OwnStateReadOnlyFiles.Status.ABSENT_LOCAL,OwnStateReadOnlyFiles.inspect(absent,"journal",1000,()->1).status());assertFalse(Files.exists(absent));}
 @Test public void boundedDirectoryNamesStayInternalAndDirect()throws Exception{Files.write(root().resolve("one"),new byte[]{1});Files.createDirectory(root().resolve("sub"));Files.write(root().resolve("sub/nested"),new byte[]{1});var r=OwnStateReadOnlyFiles.listForTest(root(),"",2,1000,()->1,attributes,()->{});assertEquals(OwnStateReadOnlyFiles.Status.DIRECTORY_NAMES,r.status());assertEquals(2,r.names().size());assertTrue(r.names().contains("sub"));assertFalse(r.names().contains("nested"));assertFalse(r.summary().contains("one"));assertEquals(OwnStateReadOnlyFiles.Status.OVERSIZE,OwnStateReadOnlyFiles.listForTest(root(),"",1,1000,()->1,attributes,()->{}).status());}
 @Test public void directoryChangeAndDeadlineReject()throws Exception{Files.write(root().resolve("one"),new byte[]{1});var r=OwnStateReadOnlyFiles.listForTest(root(),"",256,1000,()->1,attributes,()->{try{Files.setLastModifiedTime(root(),FileTime.fromMillis(1234));}catch(Exception e){throw new RuntimeException(e);}});assertEquals(OwnStateReadOnlyFiles.Status.CHANGED,r.status());assertTrue(r.names().isEmpty());assertEquals(OwnStateReadOnlyFiles.Status.EXPIRED,OwnStateReadOnlyFiles.list(root(),"",256,1,()->1).status());}
 @Test public void sourceHasNoWriteLockOrCreationCalls()throws Exception{String rel="app/src/main/java/com/aliothmoon/maafw/once/OwnStateReadOnlyFiles.java";Path f=Path.of(System.getProperty("staging.root",".."),rel);String s=Files.readString(f);for(String forbidden:new String[]{"StandardOpenOption.WRITE","StandardOpenOption.CREATE","Files.create",".lock(",".tryLock(","Files.walk("})assertFalse(forbidden,s.contains(forbidden));assertTrue(s.contains("Set.of(StandardOpenOption.READ,LinkOption.NOFOLLOW_LINKS)"));String inspect=s.substring(s.indexOf("static Result inspect("),s.indexOf("record ListResult"));assertFalse(inspect.contains("newByteChannel"));}
 @Test public void failedReadsConsumeReservedBudget()throws Exception{
  Path f=root().resolve("reserved");Files.write(f,new byte[]{1,2,3});
  var changed=OwnStateReadOnlyFiles.readForTest(root(),"reserved",1000,()->1,()->{try{Files.setLastModifiedTime(f,FileTime.fromMillis(1234));}catch(Exception e){throw new RuntimeException(e);}},attributes,3);
  assertEquals(OwnStateReadOnlyFiles.Status.CHANGED,changed.status());assertEquals(3,changed.reservedBytes());assertNull(changed.bytes());
  var second=OwnStateReadOnlyFiles.readForTest(root(),"reserved",1000,()->1,()->{fail("must reject before read callback");},attributes,3-changed.reservedBytes());
  assertEquals(OwnStateReadOnlyFiles.Status.OVERSIZE,second.status());assertEquals(0,second.reservedBytes());
 }
 @Test public void ioFailureAndExpiryDoNotRefundReservation()throws Exception{
  Files.write(root().resolve("reserved"),new byte[]{1,2});
  var failed=OwnStateReadOnlyFiles.readForTest(root(),"reserved",1000,()->1,()->{throw new IllegalStateException("PRIVATE");},attributes,2);
  assertEquals(OwnStateReadOnlyFiles.Status.IO_UNKNOWN,failed.status());assertEquals(2,failed.reservedBytes());assertFalse(failed.summary().contains("PRIVATE"));
  AtomicLong now=new AtomicLong(1);var expired=OwnStateReadOnlyFiles.readForTest(root(),"reserved",1000,now::get,()->now.set(1000),attributes,2);
  assertEquals(OwnStateReadOnlyFiles.Status.EXPIRED,expired.status());assertEquals(2,expired.reservedBytes());
 }
 @Test public void insufficientRemainingRejectsBeforeContentRead()throws Exception{
  Files.write(root().resolve("reserved"),new byte[]{1,2,3});
  var r=OwnStateReadOnlyFiles.readForTest(root(),"reserved",1000,()->1,()->fail("must not read"),attributes,2);
  assertEquals(OwnStateReadOnlyFiles.Status.OVERSIZE,r.status());assertEquals(0,r.reservedBytes());assertNull(r.bytes());
 }
}
